// Keep the public manifest and first-paint randomizer in sync with the files.
// Automatically regenerated by npm prebuild/predev when photos change.
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { makePreviewPNGDataURI } from './login-preview-png.mjs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const folder = resolve(root, 'public/login-backgrounds');
const entries = await readdir(folder, { withFileTypes: true });
const photos = entries
  .filter(entry => entry.isFile() && /\.(png|jpe?g|webp|avif)$/i.test(entry.name))
  .map(entry => entry.name)
  .sort((a, b) => a.localeCompare(b, 'vi', { numeric: true }));
const urls = photos.map(name => '/login-backgrounds/' + encodeURIComponent(name));
const manifest = {
  version: 1,
  title: 'QL Ảnh — login background collection',
  description: 'Auto-rotating login backgrounds; regenerated from the images in this directory during build.',
  images: photos.map((name, i) => ({ src: urls[i], alt: name.replace(/\.[^.]+$/, '') }))
};
await writeFile(resolve(folder, 'backgrounds.json'), JSON.stringify(manifest, null, 2) + '\n', 'utf8');
// Generate a real, tiny preview of the SAME photo, not a second background.
// The preview lives inside bootstrap.js and can be painted before the full
// 1.6–1.9 MB image is downloaded. PNG decoding uses Node's built-in zlib;
// no external image service, dependency or new monthly cost is required.
const previews = {};
for (let i=0; i<photos.length; i++) {
  if (!/\.png$/i.test(photos[i])) continue;
  try {
    previews[urls[i]] = makePreviewPNGDataURI(await readFile(resolve(folder,photos[i])),144);
  } catch(error) {
    throw Error('Cannot prepare login preview for '+photos[i]+': '+error.message);
  }
}
const boot = `// Auto-generated by scripts/generate-login-backgrounds.mjs. Do not edit.
(() => {
  'use strict';
  const images = ${JSON.stringify(urls)};
  const previews = ${JSON.stringify(previews)};
  function randomOrder(values) {
    for (let i = values.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [values[i], values[j]] = [values[j], values[i]];
    }
    return values;
  }
  const order = randomOrder(images.slice());
  // Keep the first screen photographic even if a future upload uses a
  // format without an embedded preview. Other formats still rotate later.
  if (order.length && !previews[order[0]]) {
    const available = order.map((src,i)=>previews[src]?i:-1).filter(i=>i>=0);
    if (available.length) {
      const pos=available[Math.floor(Math.random()*available.length)];
      [order[0],order[pos]]=[order[pos],order[0]];
    }
  }
  try {
    const last = sessionStorage.getItem('vl-login-previous-opening-photo');
    if (order.length > 1 && order[0] === last) {
      const position = 1 + Math.floor(Math.random() * (order.length - 1));
      [order[0], order[position]] = [order[position], order[0]];
    }
    if (order[0]) sessionStorage.setItem('vl-login-previous-opening-photo', order[0]);
  } catch (_) {}
  const initial = order[0] || null;
  const preview = initial && previews[initial] || null;
  window.__vlLoginBackgroundBoot = {images, order, initial, preview};
  // Start fetching the chosen photo immediately, before Tailwind, Google
  // scripts, stylesheets or the body markup can delay the request.
  if (initial) {
    const link = document.createElement('link');
    link.rel = 'preload';
    link.as = 'image';
    link.href = initial;
    link.setAttribute('fetchpriority', 'high');
    document.head.appendChild(link);
  }
  if (preview) document.documentElement.style.setProperty('--vl-login-first-photo', 'url(' + JSON.stringify(preview) + ')');
})();
`;
await writeFile(resolve(folder, 'bootstrap.js'), boot, 'utf8');
console.log('[login backgrounds] ' + photos.length + ' image(s); ' + Object.keys(previews).length + ' inline photo previews generated.');
